const __css = "*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\n:root {\n  --me-bg: #0f0f1a;\n  --me-surface: #1a1b2e;\n  --me-card: #23242c;\n  --me-border: rgba(255,255,255,0.08);\n  --me-text: #e5e7eb;\n  --me-muted: #9ca3af;\n  --me-primary: #7c3aed;\n  --me-primary-hover: #6d28d9;\n  --me-error: #f87171;\n  --me-radius: 12px;\n  --me-font: -apple-system, BlinkMacSystemFont, \"Segoe UI\", system-ui, sans-serif;\n}\n\nbody {\n  font-family: var(--me-font);\n  background: var(--me-bg);\n  color: var(--me-text);\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* ── Container ────────────────────────────────────── */\n.me-container {\n  width: 100%;\n  max-width: 680px;\n  padding: 24px;\n}\n\n/* ── Upload Zone ──────────────────────────────────── */\n.me-upload {\n  background: var(--me-card);\n  border: 2px dashed var(--me-border);\n  border-radius: var(--me-radius);\n  padding: 56px 32px;\n  text-align: center;\n  cursor: pointer;\n  transition: border-color 0.2s, background 0.2s;\n}\n\n.me-upload:hover {\n  border-color: var(--me-primary);\n  background: rgba(124,58,237,0.04);\n}\n\n.me-upload--drag {\n  border-color: var(--me-primary);\n  background: rgba(124,58,237,0.08);\n}\n\n.me-upload-icon { color: var(--me-muted); margin-bottom: 16px; }\n.me-upload h2 { font-size: 20px; font-weight: 700; margin-bottom: 8px; }\n.me-upload-hint { font-size: 14px; color: var(--me-muted); margin-bottom: 20px; }\n.me-upload-note { font-size: 12px; color: var(--me-muted); margin-top: 12px; opacity: 0.6; }\n\n/* ── Buttons ──────────────────────────────────────── */\n.me-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 24px;\n  font-size: 14px;\n  font-weight: 600;\n  font-family: var(--me-font);\n  color: var(--me-text);\n  background: rgba(255,255,255,0.06);\n  border: 1px solid var(--me-border);\n  border-radius: 8px;\n  cursor: pointer;\n  transition: background 0.15s, border-color 0.15s, transform 0.1s;\n}\n\n.me-btn:hover {\n  background: rgba(255,255,255,0.1);\n  border-color: rgba(255,255,255,0.12);\n}\n\n.me-btn:active { transform: scale(0.97); }\n\n.me-btn--primary {\n  background: var(--me-primary);\n  border-color: var(--me-primary);\n  color: #fff;\n}\n\n.me-btn--primary:hover {\n  background: var(--me-primary-hover);\n  border-color: var(--me-primary-hover);\n}\n\n.me-btn--ghost {\n  background: transparent;\n  border-color: transparent;\n  color: var(--me-primary);\n  padding: 8px 12px;\n}\n\n.me-btn--ghost:hover { background: rgba(124,58,237,0.08); }\n\n/* ── Editor Panel ─────────────────────────────────── */\n.me-editor { animation: fadeIn 0.25s ease; }\n\n@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(8px); }\n  to   { opacity: 1; transform: translateY(0); }\n}\n\n.me-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 24px;\n}\n\n.me-title { font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }\n\n/* ── Import Drop Zone ────────────────────────────── */\n.me-import-drop {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  margin-bottom: 16px;\n  padding: 20px 16px;\n  background: rgba(255,255,255,0.02);\n  border: 2px dashed var(--me-border);\n  border-radius: 10px;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s;\n  user-select: none;\n}\n\n.me-import-drop:hover {\n  border-color: var(--me-primary);\n  background: rgba(99,102,241,0.04);\n}\n\n.me-import-drop--drag {\n  border-color: var(--me-primary);\n  background: rgba(99,102,241,0.08);\n}\n\n.me-import-drop-icon {\n  font-size: 24px;\n  line-height: 1;\n  margin-bottom: 2px;\n}\n\n.me-import-drop-text {\n  font-size: 13px;\n  color: var(--me-text);\n  text-align: center;\n}\n\n.me-import-drop-text strong {\n  color: var(--me-primary);\n}\n\n.me-import-drop-hint {\n  font-size: 11px;\n  color: var(--me-muted);\n}\n\n/* ── Profiles ─────────────────────────────────────── */\n.me-profiles {\n  margin-bottom: 16px;\n  padding: 12px 16px;\n  background: rgba(255,255,255,0.03);\n  border: 1px solid var(--me-border);\n  border-radius: 8px;\n}\n\n.me-profiles-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 10px;\n}\n\n.me-profiles-header h3 {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--me-text);\n}\n\n.me-profiles-scroll {\n  display: flex;\n  gap: 10px;\n  overflow-x: auto;\n  padding-bottom: 4px;\n  scrollbar-width: thin;\n  scrollbar-color: var(--me-border) transparent;\n}\n\n.me-profiles-scroll::-webkit-scrollbar {\n  height: 6px;\n}\n\n.me-profiles-scroll::-webkit-scrollbar-thumb {\n  background: var(--me-border);\n  border-radius: 3px;\n}\n\n.me-profiles-empty {\n  color: var(--me-muted);\n  font-size: 13px;\n  margin: 0;\n  white-space: nowrap;\n}\n\n.me-profile-card {\n  flex: 0 0 160px;\n  position: relative;\n  padding: 12px;\n  background: var(--me-surface);\n  border: 1px solid var(--me-border);\n  border-radius: 8px;\n  cursor: pointer;\n  transition: border-color 0.15s, background 0.15s;\n  user-select: none;\n}\n\n.me-profile-card:hover {\n  border-color: var(--me-primary);\n  background: rgba(99,102,241,0.06);\n}\n\n.me-profile-del {\n  position: absolute;\n  top: 4px;\n  right: 4px;\n  width: 22px;\n  height: 22px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  color: var(--me-muted);\n  font-size: 16px;\n  line-height: 1;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: color 0.12s, background 0.12s;\n  padding: 0;\n}\n\n.me-profile-del:hover {\n  color: var(--me-error);\n  background: rgba(248,113,113,0.12);\n}\n\n.me-profile-name {\n  font-size: 14px;\n  font-weight: 600;\n  color: var(--me-text);\n  margin-bottom: 4px;\n  padding-right: 18px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.me-profile-preview {\n  font-size: 12px;\n  color: var(--me-muted);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.me-btn--small {\n  padding: 6px 14px;\n  font-size: 12px;\n}\n\n/* ── Sections ─────────────────────────────────────── */\n.me-section {\n  background: var(--me-card);\n  border: 1px solid var(--me-border);\n  border-radius: var(--me-radius);\n  padding: 20px;\n  margin-bottom: 16px;\n}\n\n.me-section h3 {\n  font-size: 13px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--me-muted);\n  margin-bottom: 16px;\n}\n\n/* ── File Info Table ──────────────────────────────── */\n.me-table { width: 100%; border-collapse: collapse; }\n\n.me-table td {\n  padding: 8px 12px;\n  font-size: 14px;\n  border-bottom: 1px solid var(--me-border);\n}\n\n.me-table td:first-child {\n  color: var(--me-muted);\n  font-weight: 500;\n  width: 140px;\n}\n\n.me-table tr:last-child td { border-bottom: none; }\n\n/* ── Metadata Grid ────────────────────────────────── */\n.me-exif-group { margin-bottom: 16px; }\n.me-exif-group:last-child { margin-bottom: 0; }\n\n.me-exif-group h4 {\n  font-size: 12px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--me-primary);\n  margin-bottom: 8px;\n}\n\n.me-exif-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 4px;\n}\n\n@media (max-width: 500px) {\n  .me-exif-grid { grid-template-columns: 1fr; }\n}\n\n.me-exif-item {\n  display: flex;\n  flex-direction: column;\n  padding: 6px 10px;\n  background: rgba(255,255,255,0.03);\n  border-radius: 6px;\n  font-size: 13px;\n}\n\n.me-exif-label {\n  color: var(--me-muted);\n  font-size: 11px;\n  font-weight: 500;\n  margin-bottom: 2px;\n}\n\n.me-exif-value {\n  color: var(--me-text);\n  word-break: break-all;\n}\n\n/* ── Form ──────────────────────────────────────────── */\n.me-form {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.me-field {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.me-label {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--me-muted);\n}\n\n.me-field input,\n.me-field textarea,\n.me-field select {\n  font-family: var(--me-font);\n  font-size: 14px;\n  color: var(--me-text);\n  background: var(--me-surface);\n  border: 1px solid var(--me-border);\n  border-radius: 8px;\n  padding: 10px 12px;\n  outline: none;\n  transition: border-color 0.15s;\n}\n\n.me-field input:focus,\n.me-field textarea:focus,\n.me-field select:focus { border-color: var(--me-primary); }\n\n.me-field input::placeholder,\n.me-field textarea::placeholder { color: rgba(255,255,255,0.2); }\n\n.me-form .me-btn--primary {\n  align-self: flex-start;\n  margin-top: 4px;\n}\n\n/* ── Contact Grid ─────────────────────────────────── */\n.me-contact-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 12px;\n  padding: 16px;\n  background: rgba(255,255,255,0.02);\n  border: 1px dashed var(--me-border);\n  border-radius: var(--me-radius);\n  position: relative;\n}\n\n@media (max-width: 500px) {\n  .me-contact-grid { grid-template-columns: 1fr; }\n}\n\n/* ── Custom Fields ────────────────────────────────── */\n.me-custom-section {\n  padding: 16px;\n  border: 1px dashed var(--me-border);\n  border-radius: var(--me-radius);\n}\n\n.me-custom-row {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 8px;\n  align-items: center;\n}\n\n.me-custom-row input {\n  flex: 1;\n}\n\n.me-custom-remove {\n  background: none;\n  border: none;\n  color: var(--me-error);\n  font-size: 20px;\n  cursor: pointer;\n  padding: 4px 8px;\n  line-height: 1;\n  border-radius: 6px;\n  transition: background 0.12s;\n}\n\n.me-custom-remove:hover { background: rgba(248,113,113,0.12); }\n\n/* ── Misc ──────────────────────────────────────────── */\n.me-muted { color: var(--me-muted); font-size: 14px; }\n.me-error { color: var(--me-error); font-size: 13px; }\n";
const __body = "\n  <div class=\"me-container\" id=\"app\">\n\n    <!-- Upload Zone -->\n    <div class=\"me-upload\" id=\"uploadZone\">\n      <div class=\"me-upload-icon\">\n        <svg width=\"64\" height=\"64\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/>\n          <polyline points=\"17 8 12 3 7 8\"/>\n          <line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"/>\n        </svg>\n      </div>\n      <h2>Subir archivo</h2>\n      <p class=\"me-upload-hint\">Arrastra una imagen aquí o haz clic para seleccionar</p>\n      <input type=\"file\" id=\"fileInput\" accept=\"image/jpeg,image/png,image/tiff\" hidden />\n      <button class=\"me-btn\" id=\"selectBtn\">Seleccionar archivo</button>\n      <p class=\"me-upload-note\">JPEG, PNG, TIFF</p>\n    </div>\n\n    <!-- Editor Panel -->\n    <div class=\"me-editor\" id=\"editorPanel\" hidden>\n      <header class=\"me-header\">\n        <h1 class=\"me-title\">MetadataEditor</h1>\n        <button class=\"me-btn me-btn--ghost\" id=\"newFileBtn\">+ Nuevo archivo</button>\n      </header>\n\n      <!-- Import Drop Zone -->\n      <div class=\"me-import-drop\" id=\"importDropZone\">\n        <span class=\"me-import-drop-icon\">📥</span>\n        <span class=\"me-import-drop-text\">Arrastra aquí un <strong>.txt</strong> o <strong>imagen</strong> para importar metadatos</span>\n        <span class=\"me-import-drop-hint\">o haz clic para seleccionar archivo</span>\n        <input type=\"file\" id=\"importFileInput\" accept=\".txt,image/jpeg,image/png,image/tiff\" hidden />\n      </div>\n\n      <!-- Profiles Section -->\n      <div class=\"me-profiles\">\n        <div class=\"me-profiles-header\">\n          <h3>Perfiles guardados</h3>\n          <button type=\"button\" class=\"me-btn me-btn--small\" id=\"saveProfileBtn\">+ Guardar actual</button>\n        </div>\n        <div class=\"me-profiles-scroll\" id=\"profilesContainer\">\n          <p class=\"me-profiles-empty\">No hay perfiles guardados</p>\n        </div>\n      </div>\n\n      <!-- Edit Form -->\n      <section class=\"me-section\">\n        <h3>Editar metadatos</h3>\n        <form id=\"metaForm\" class=\"me-form\">\n\n          <label class=\"me-field\">\n            <span class=\"me-label\">Copyright Notice</span>\n            <input type=\"text\" id=\"fieldCopyrightNotice\" placeholder=\"Ej: © 2026 Tu Nombre. Todos los derechos reservados.\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Creator / Author</span>\n            <input type=\"text\" id=\"fieldCreator\" placeholder=\"Nombre del fotógrafo o empresa\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Credit Line</span>\n            <input type=\"text\" id=\"fieldCreditLine\" placeholder=\"Quién debe recibir el crédito\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Rights Usage Terms</span>\n            <input type=\"text\" id=\"fieldRightsUsageTerms\" placeholder=\"Condiciones de uso\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Web Statement of Rights</span>\n            <input type=\"url\" id=\"fieldWebStatement\" placeholder=\"https://ejemplo.com/licencia\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Licensor URL</span>\n            <input type=\"url\" id=\"fieldLicensorURL\" placeholder=\"https://ejemplo.com/contacto\" />\n          </label>\n          <label class=\"me-field\">\n            <span class=\"me-label\">Source</span>\n            <input type=\"text\" id=\"fieldSource\" placeholder=\"Fuente original\" />\n          </label>\n\n          <div class=\"me-contact-grid\">\n            <label class=\"me-field\">\n              <span class=\"me-label\">Contacto Email</span>\n              <input type=\"email\" id=\"fieldContactEmail\" placeholder=\"email@ejemplo.com\" />\n            </label>\n            <label class=\"me-field\">\n              <span class=\"me-label\">Contacto Web</span>\n              <input type=\"url\" id=\"fieldContactWeb\" placeholder=\"https://ejemplo.com\" />\n            </label>\n            <label class=\"me-field\">\n              <span class=\"me-label\">Contacto Teléfono</span>\n              <input type=\"tel\" id=\"fieldContactPhone\" placeholder=\"+34 123 456 789\" />\n            </label>\n            <label class=\"me-field\">\n              <span class=\"me-label\">Contacto Dirección</span>\n              <input type=\"text\" id=\"fieldContactAddress\" placeholder=\"Dirección postal\" />\n            </label>\n          </div>\n\n          <div class=\"me-custom-section\">\n            <span class=\"me-label\" style=\"display:block;margin-bottom:10px;\">Campos personalizados</span>\n            <div id=\"customFieldsContainer\"></div>\n            <button type=\"button\" class=\"me-btn me-btn--ghost me-btn--add\" id=\"addCustomBtn\">+ Añadir campo</button>\n          </div>\n\n          <button type=\"submit\" class=\"me-btn me-btn--primary\" id=\"downloadBtn\">\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>\n            Descargar con metadatos\n          </button>\n        </form>\n      </section>\n\n      <!-- File Info -->\n      <section class=\"me-section\">\n        <h3>Información del archivo</h3>\n        <table class=\"me-table\" id=\"fileInfo\">\n          <tr><td>Nombre</td><td id=\"infoName\">—</td></tr>\n          <tr><td>Tamaño</td><td id=\"infoSize\">—</td></tr>\n          <tr><td>Tipo</td><td id=\"infoType\">—</td></tr>\n          <tr><td>Última modificación</td><td id=\"infoDate\">—</td></tr>\n        </table>\n      </section>\n\n      <!-- Native / Camera metadata -->\n      <section class=\"me-section\" id=\"metaSection\" hidden>\n        <h3 id=\"metaSectionTitle\">Metadatos</h3>\n        <div id=\"metaDisplay\"></div>\n      </section>\n\n      <!-- Raw text metadata -->\n      <section class=\"me-section\" id=\"textMetaSection\" hidden>\n        <h3>Metadatos de texto</h3>\n        <div id=\"textMetaDisplay\"></div>\n      </section>\n    </div>\n  </div>\n\n  \n";

